<script lang="ts">
  import {onMount,untrack} from 'svelte';import {rpc,errorText,bytes,type Download} from '../lib/api';import {notify} from '../lib/ui';import Icon from './Icon.svelte';
  let {openFolder,newDownload,revision}:{openFolder:(p:string)=>void;newDownload:()=>void;revision:number}=$props();let jobs=$state<Download[]>([]);let error=$state('');let busy=$state(false);let speeds=$state<Record<string,number>>({});let samples=new Map<string,{bytes:number;time:number}>();let alive=true;let pendingRefresh=false;let pendingForce=false;let timer:ReturnType<typeof setTimeout>;
  $effect(()=>{revision;untrack(()=>{clearTimeout(timer);void refresh();});});
  async function refresh(force=false){if(busy){pendingRefresh=true;pendingForce ||= force;return;}busy=true;try{const next=await rpc('download_list',{refresh:force});if(!alive)return;const now=Date.now();const speed:Record<string,number>={};for(const j of next){const prev=samples.get(j.id);speed[j.id]=prev&&j.status==='Downloading'?Math.max(0,(j.downloaded-prev.bytes)/((now-prev.time)/1000)):0;samples.set(j.id,{bytes:j.downloaded,time:now});}speeds=speed;jobs=next;error='';}catch(e){if(alive)error=errorText(e);}finally{busy=false;const forceNext=pendingForce;if(alive&&(pendingRefresh||jobs.some(j=>['Starting','Waiting','Downloading'].includes(j.status))))timer=setTimeout(()=>refresh(forceNext),pendingRefresh?0:2000);pendingRefresh=false;pendingForce=false;}}
  onMount(()=>{alive=true;void refresh(true);return()=>{alive=false;clearTimeout(timer);};});
  async function retry(job:Download){if(job.authenticated||job.method==='POST'||job.headerCount>0){notify('Request credentials and bodies were removed. Reopen the download in the browser and approve a fresh request; POST is never retried automatically.');return;}try{await rpc('download_start',{url:job.url,directory:job.directory,filename:job.filename});clearTimeout(timer);await refresh();}catch(e){notify(e);}}
</script>
<div class="app-column downloads-app"><div class="toolbar"><span class="muted">SERVER DOWNLOADS</span><span class="spacer"></span><button disabled={busy} onclick={()=>{clearTimeout(timer);void refresh(true);}}><Icon name="refresh" size={16}/> Refresh</button><button class="primary" onclick={newDownload}><Icon name="plus" size={16}/> New download</button></div>
{#if error}<div class="error-box">{error}</div>{/if}<div class="download-list">{#each jobs as job}<article class="download-card"><div class="download-icon"><Icon name={job.status==='Completed'?'check':job.status==='Failed'?'close':'downloads'} size={24}/></div><div class="download-details"><strong>{job.filename}</strong><div class="muted ellipsis">{job.directory}</div><div class="download-progress" class:indeterminate={!job.total&&job.status==='Downloading'}><div style:width={job.total?`${Math.min(100,100*job.downloaded/job.total)}%`:'0%'}></div></div><div class="download-meta"><span class:failed={job.status==='Failed'}>{job.status}</span><span>{bytes(job.downloaded)}{job.total?` / ${bytes(job.total)} · ${Math.round(job.downloaded/job.total*100)}%`:' · total unknown'}</span>{#if speeds[job.id]>0}<span>{bytes(speeds[job.id])}/s</span>{/if}<span>{job.backend} · detached</span></div><small class="muted">Started {new Date(job.started*1000).toLocaleString()}</small>{#if job.error}<pre class="download-error">{job.error}</pre>{/if}</div><div class="download-actions">{#if ['Waiting','Starting','Downloading'].includes(job.status)}<button title="Cancel" onclick={async()=>{try{await rpc('download_cancel',{id:job.id});}catch(e){notify(e);}}}><Icon name="close" size={16}/></button>{:else if job.status!=='Completed'}<button onclick={()=>retry(job)}><Icon name="refresh" size={16}/> Retry</button>{/if}<button title="Open destination folder" onclick={()=>openFolder(job.directory)}><Icon name="files" size={17}/> Open Folder</button></div></article>{/each}{#if !jobs.length&&!busy}<div class="empty-state"><Icon name="downloads" size={40}/><h3>Give your server the download</h3><p>Browse locally. Save files directly to Linux.</p><button class="primary" onclick={newDownload}>Download a direct URL</button></div>{/if}</div><div class="statusbar">{jobs.length} jobs <span>File bodies never pass through this client</span></div></div>
